VIEWER = 'src/components/CadViewer.tsx'
PKG = 'package.json'

def d(s): return base64.b64decode(s).decode('utf-8')

def parse_args(argv):
    root, do_build = '.', True
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--root': root = argv[i+1]; i += 2; continue
        if a == '--no-build': do_build = False
        i += 1
    return root, do_build

def write_new_files(root):
    for rel, enc in FILES.items():
        path = os.path.join(root, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        content = d(enc)
        if os.path.exists(path) and open(path, encoding='utf-8').read() == content:
            print("  = inchangé  ", rel)
        else:
            open(path, 'w', encoding='utf-8').write(content)
            print("  + écrit     ", rel)

def patch_viewer(root):
    path = os.path.join(root, VIEWER)
    if not os.path.exists(path):
        print("!! introuvable :", VIEWER); sys.exit(1)
    src = open(path, encoding='utf-8').read()
    applied, skipped = 0, 0
    for name, dm, o, nw in EDITS:
        marker, old, new = d(dm), d(o), d(nw)
        if marker in src:
            print("  = déjà là   ", name); skipped += 1; continue
        if old not in src:
            print("!! ANCRE INTROUVABLE pour", name, "— arrêt (aucune écriture partielle du viewer).")
            sys.exit(2)
        src = src.replace(old, new, 1)
        print("  ~ patché    ", name); applied += 1
    open(path, 'w', encoding='utf-8').write(src)
    print(f"  -> {applied} patch(s) appliqué(s), {skipped} déjà présent(s).")

def patch_pkg(root):
    path = os.path.join(root, PKG)
    pkg = json.load(open(path, encoding='utf-8'))
    pkg.setdefault('scripts', {})
    pkg['scripts'].setdefault('test', 'vitest run')
    pkg['scripts'].setdefault('test:watch', 'vitest')
    pkg['scripts'].setdefault('test:ci', 'vitest run')
    pkg.setdefault('devDependencies', {})
    if 'vitest' not in pkg['devDependencies']:
        pkg['devDependencies']['vitest'] = '^4.1.0'
    json.dump(pkg, open(path, 'w', encoding='utf-8'), indent=2, ensure_ascii=False)
    open(path, 'a', encoding='utf-8').write('\n')
    print("  ~ package.json : scripts test + devDep vitest")

def run(cmd, root):
    print("\n$ " + " ".join(cmd))
    r = subprocess.run(cmd, cwd=root)
    if r.returncode != 0:
        print("!! échec :", " ".join(cmd), "(rc=%d) — rien n'est poussé." % r.returncode)
        sys.exit(r.returncode)

def main():
    root, do_build = parse_args(sys.argv[1:])
    print("== Bilnov L2/incr.1 — application ==")
    print("[1/3] Fichiers neufs (module pur + tests + config vitest)")
    write_new_files(root)
    print("[2/3] Patch du viewer + package.json")
    patch_viewer(root)
    patch_pkg(root)
    print("[3/3] Installation + tests" + ("" if not do_build else " + build (bloquants)"))
    run(["npm", "install"], root)
    run(["npm", "run", "test"], root)
    if do_build:
        run(["npm", "run", "build"], root)
    print("\nOK. Tests verts" + (" et build OK." if do_build else "."))
    print("Revue puis, si tout est vert :  git add -A && git commit -m \"feat(cad): mesures editables + unite permanente + tests vitest (L2)\" && git push")

if __name__ == '__main__':
    main()
